from lib import *
S = SS('p30')
steps = [
    step("urllib3 的 Retry.parse_retry_after 对各种写法的解析:'5' 和 ' 5 ' 都是 5 秒;'0' 是 0;'3600' 是 3600;'86400' 被截成 21600 秒(Retry.DEFAULT_RETRY_AFTER_MAX,6 小时);HTTP-date 形式(比现在晚 10 秒)是 9.6 秒,早于现在的日期是 0;'-3'、'1.5'、'soon'、空串都抛 InvalidHeader。能自动重试的状态码集合 RETRY_AFTER_STATUS_CODES 是 [413, 429, 503]。sleep_for_retry 的实现就是 time.sleep(retry_after)。", t=tl(S(1)), done=lidx(S(1), "'5'", "'0'", "'3600'", 'Mon, 12 Oct 2026 02:49:59'), mark=lidx(S(1), "'-3'", "'1.5'", "'soon'", "'86400'"), kv=KV([['整数秒', '直接使用(最大 21600)'], ['HTTP-date', '换算成距现在的秒数,过期为 0'], ['小数、负数、乱写', '抛 InvalidHeader']], ['小数、负数、乱写'])),
    step("限流服务器(每个自然秒最多 5 个请求,超出回 429 加 Retry-After),客户端连续发 20 个请求、最多重试 6 次。不重试:成功 5、失败 15。重试但忽略 Retry-After、不等待:成功 5、失败 15,服务器却收到 110 个请求(其中 105 个 429)——6 次重试在同一秒里用光。忽略 Retry-After 但用 backoff_factor=0.2:20 个全成功,2.8 秒,服务器收到 28 个(8 个 429)。遵守 Retry-After(urllib3 默认):20 个全成功,3.0 秒,服务器收到 23 个(只有 3 个 429)。", t=tl(S(2)), done=lidx(S(2), 'backoff_factor=0.2', '遵守 Retry-After'), mark=lidx(S(2), '固定 backoff 0(立刻重试)'), b=bars([['立刻重试:服务器收到', 110, '110'], ['backoff 0.2:服务器收到', 28, '28'], ['遵守 Retry-After:服务器收到', 23, '23']], 110, mark=[0], done=[1, 2]), kv=KV([['立刻重试', '110 个请求,仍失败 15 个'], ['backoff_factor=0.2', '28 个请求,2.8 秒'], ['遵守 Retry-After', '23 个请求,3.0 秒']], ['遵守 Retry-After'])),
    step("Retry-After 写成 HTTP-date(绝对时间)时 urllib3 同样遵守:12 个请求全部成功,总耗时 1.6 秒,服务器收到 14 个请求(2 个 429)。", t=tl(S(3)), done=lidx(S(3), '12 个请求'), kv=KV([['格式', 'HTTP-date'], ['结果', '12 个全成功,1.6 秒'], ['服务器收到', '14 个请求']], ['结果'])),
    step("Retry-After 的值很大时:urllib3 有上限 Retry.DEFAULT_RETRY_AFTER_MAX = 21600 秒;Retry().parse_retry_after('86400') 是 21600 秒,Retry(retry_after_max=60).parse_retry_after('3600') 是 60 秒。服务器回 429 + Retry-After: 3:默认上限下重试等了 3.0 秒;retry_after_max=1 时只等 1.0 秒。服务器可以让你的爬虫线程睡很久,要不要接受由 retry_after_max 决定。", t=tl(S(4)), done=lidx(S(4), 'retry_after_max=1', 'parse_retry_after'), mark=lidx(S(4), 'retry_after_max=默认'), b=bars([['默认上限:等待 秒', 3.0, '3.0'], ['retry_after_max=1:等待 秒', 1.0, '1.0']], 3, mark=[0], done=[1]), kv=KV([['默认上限', '21600 秒(6 小时)'], ['retry_after_max=1', '把 3 秒的等待压到 1 秒'], ['建议', '按自己能接受的最长等待设置']], ['建议'])),
    step("哪些响应会被重试(源码 is_retry:状态码在 status_forcelist 里,或总重试数大于 0 且带了 Retry-After 且状态码属于 413/429/503)。503 + Retry-After: 1、status_forcelist=[500]:重试成功,服务器收到 2 个请求;503 没有 Retry-After:不重试,服务器只收到 1 个;429 + Retry-After、status_forcelist 为空:仍然重试,收到 2 个;500 + Retry-After、status_forcelist 为空:不重试;302 + Retry-After:不重试。也就是说,只要给 Retry 设了 total,服务器带着 Retry-After 返回 429/503 就会让你的客户端重试,哪怕你没把它们列进 status_forcelist。", t=tl(S(5)), done=lidx(S(5), '503 + Retry-After: 1,status_forcelist=[500]', '429 + Retry-After: 1,status_forcelist=[]', '503 + Retry-After: 1,status_forcelist=[503]'), mark=lidx(S(5), '503(无 Retry-After)', '500 + Retry-After', '302 + Retry-After'), kv=KV([['503/429 + Retry-After', '总会被重试(只要设了 total)'], ['500 + Retry-After', '不重试'], ['503 无 Retry-After', '不在 forcelist 就不重试']], ['503/429 + Retry-After'])),
]
A = mkartp('p30', 30, '爬虫,429,Retry-After,限流,urllib3,Retry,requests,Python,真实验证,动画演示',
    '实测爬虫对 429 和 Retry-After 的处理:立刻重试向限流服务器发了 110 个请求仍失败 15 个,遵守 Retry-After 只发 23 个、3.0 秒全部成功;urllib3 支持整数和 HTTP-date 两种写法,默认上限 21600 秒;429/503 只要带 Retry-After,即使不在 status_forcelist 里也会被重试。',
    '被限流的时候,服务器通常会用 429 加 Retry-After 告诉你该等多久。你的爬虫是听,还是立刻重试?这篇用一个固定窗口限流服务器,量一量听与不听的差别,并弄清 urllib3 到底怎么解析这个头、会重试哪些响应。',
    [('110 对 23', '限流服务器下 20 个请求:立刻重试与遵守 Retry-After 时服务器收到的请求数'), ('21600 秒', 'urllib3 对 Retry-After 的默认上限(6 小时),retry_after_max 可改'), ('503 + Retry-After', '即使 status_forcelist 里没有 503,也会被重试')],
    [('怎么解析', '<p>urllib3 的 <code>Retry.parse_retry_after</code> 接受整数秒(允许前后空白)和 HTTP-date;小数、负数、乱写的值抛 <code>InvalidHeader</code>;日期早于现在是 0 秒;值超过 <code>retry_after_max</code> 就取上限(默认 21600 秒)。</p>'),
     ('听与不听', '<p>每个自然秒 5 个请求的限流下,20 个请求:不重试成功 5 个;重试但立刻重来,6 次重试在同一秒里用光,服务器收到 110 个请求却仍有 15 个失败;遵守 <code>Retry-After</code> 全部成功,服务器只多收到 3 个 429。即使忽略头,<code>backoff_factor=0.2</code> 的指数等待也成功了(28 个请求),但不如直接听服务器的。</p>'),
     ('日期写法', '<p><code>Retry-After</code> 也可以写成 HTTP-date,urllib3 同样遵守,换算成距现在的秒数。</p>'),
     ('上限', '<p>服务器能决定你的客户端睡多久。默认上限 6 小时,太长了:按能接受的最长等待设置 <code>retry_after_max</code>(演示里 3 秒的等待被压到 1 秒)。</p>'),
     ('哪些响应会被重试', '<p>只要给 <code>Retry</code> 设了 <code>total</code>,带 <code>Retry-After</code> 的 413/429/503 就会被重试,不论是否在 <code>status_forcelist</code> 里;不带头的 503、带头的 500、302 都不会。要关掉就设 <code>respect_retry_after_header=False</code>(上面第二节用过)。</p>')],
    steps,
    [ENV_P + '。限流服务器:每个自然秒最多接受 5 个请求,超出回 429 与 Retry-After(窗口剩余秒数向上取整,或 HTTP-date);客户端 requests 2.34.2 的 Session 挂 HTTPAdapter(max_retries=Retry(…)),urllib3 2.7.0;“服务器收到”取服务器日志的请求数;函数行为同时读了 urllib3 的 Retry.is_retry、parse_retry_after、sleep_for_retry 源码',
     '没有验证:aiohttp 或 httpx 的 Retry-After 处理(它们没有内置);Retry-After 与 X-RateLimit-Reset、RateLimit-Remaining 等其它限流头的配合;多个客户端共享同一个限流配额;重试期间连接是否保持;非幂等方法(POST)是否会被 Retry 重试(本系列后面有 POST 重试的专门一篇);真实 API 的 429 语义'],
    '429 与 Retry-After')
